// _fixed_cloneMapStringInt32 returns a copy of x, a map[string]int32, and nil
// for a nil x.
func _fixed_cloneMapStringInt32(x map[string]int32) map[string]int32 {
	if x == nil {
		return nil
	}
	c := make(map[string]int32, len(x))
	for mk, mv := range x {
		c[strings.Clone(mk)] = mv
	}
	return c
}

